import React from "react";

/**
 * Sprig of dó bầu (Aquilaria), the tree agarwood forms in: fine gold line
 * art used as a faint corner ornament (footer only). The SVG is generated by
 * scripts/generate-patterns.mjs.
 */
export function DoBauBranch({ className = "" }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={`pointer-events-none absolute bg-[url(/patterns/do-bau-branch.svg)] bg-contain bg-center bg-no-repeat ${className}`}
    />
  );
}
